"use client";

import * as React from "react";
import { HugeiconsIcon } from "@hugeicons/react";
import { PauseIcon, PlayIcon } from "@hugeicons/core-free-icons";
import { Dots, IsoFigure, Line, Solid } from "@/components/anatomy/react/draw";
import { asksForStillness, follow, useInView } from "@/components/anatomy/react/live";
import { LiveSolid, type SolidHandle } from "@/components/anatomy/live-solid";
import { planeFrom } from "@/components/anatomy/axis-parts";
import type { Flat } from "@/components/anatomy/iso-kit";
import {
  ARM_STYLE,
  ARM_Z,
  DECK_LINES,
  DECK_PARTS,
  FRONT_LINES,
  FRONT_PARTS,
  GROOVE,
  GROOVE_IN,
  GROOVE_OUT,
  HEIGHT,
  INDEX_MARK,
  LABEL_MARKS,
  LAMP_RING,
  P,
  PHI_INNER,
  PHI_PARK,
  PITCH_MAX,
  PIVOT,
  PLATTER_LINES,
  PLATTER_PARTS,
  SPIN_RATE,
  STROBE,
  WIDTH,
  armAt,
  armParts,
  bearingFor,
  clampPhi,
  grooveSpin,
  needleAt,
  rimSpin,
  sideAt,
  spinAt,
  tourTimeFor,
} from "./turntable";
import "./the-turntable.css";

const MOST_DT = 1 / 30;
const SEEK = 0.09; // seconds for the arm to answer a reader's hand
const TURNING = 0.28; // and for the lamp to follow the platter
/** inside this the pointer's bearing from the post is noise, and the arm jumps */
const NEAR = 80;

/** the arm as it stands before the first frame: parked, resting on its cradle */
const OPENING = armParts({ phi: PHI_PARK, pitch: PITCH_MAX });

interface Live {
  clock: number;
  /** where the arm stands */
  phi: number;
  pitch: number;
  /** and where a reader who has taken hold of it wants it */
  wantPhi: number;
  wantPitch: number;
  /** how far the platter has turned, in radians */
  spin: number;
  /** how fast it is going, nought to one, which is what the lamp shows */
  turn: number;
}

export interface TheTurntableProps {
  theme?: "dark" | "light";
  className?: string;
  /** hold the tour if you want to drive it yourself */
  playing?: boolean;
  defaultPlaying?: boolean;
  onPlayingChange?: (playing: boolean) => void;
}

export function TheTurntable({ theme = "dark", className, playing: controlled, defaultPlaying = true, onPlayingChange }: TheTurntableProps) {
  const [own, setOwn] = React.useState(defaultPlaying);
  const playing = controlled ?? own;
  const setPlaying = React.useCallback(
    (next: boolean) => {
      if (controlled === undefined) setOwn(next);
      onPlayingChange?.(next);
    },
    [controlled, onPlayingChange],
  );

  /** the stage: the box the pointer is read against, and what is watched for
      the figure stopping when it scrolls out of sight */
  const root = React.useRef<HTMLDivElement | null>(null);
  const inView = useInView(root);
  const grooves = React.useRef<SVGGElement | null>(null);
  const rim = React.useRef<SVGGElement | null>(null);
  const lamp = React.useRef<SVGPathElement | null>(null);
  const handles = React.useMemo(() => ARM_STYLE.map(() => React.createRef<SolidHandle>()), []);
  const frame = React.useRef(0);
  const last = React.useRef(0);
  const grab = React.useRef(0);
  const playRef = React.useRef(playing);
  const [pressing, setPressing] = React.useState(false);

  const state = React.useRef<Live>({
    clock: 0,
    phi: PHI_PARK,
    pitch: PITCH_MAX,
    wantPhi: PHI_PARK,
    wantPitch: PITCH_MAX,
    spin: 0,
    turn: 0,
  });

  const paint = React.useCallback(() => {
    const s = state.current;
    const next = armParts({ phi: s.phi, pitch: s.pitch });
    for (let index = 0; index < next.length; index++) handles[index]?.current?.apply(next[index]!);
    grooves.current?.setAttribute("transform", grooveSpin(s.spin));
    rim.current?.setAttribute("transform", rimSpin(s.spin));
    // the lamp is on the motor, so it answers to the same number the platter does
    if (lamp.current) lamp.current.style.opacity = (0.18 + 0.82 * s.turn).toFixed(3);
    const host = root.current;
    if (host) {
      const mm = Math.round(needleAt(s.phi));
      const through = Math.max(0, Math.min(100, Math.round(sideAt(s.phi) * 100)));
      const text =
        needleAt(s.phi) > GROOVE_OUT
          ? "parked, off the record"
          : `${mm} millimetres from the spindle, ${through} per cent through the side`;
      if (host.getAttribute("aria-valuetext") !== text) {
        host.setAttribute("aria-valuenow", String(through));
        host.setAttribute("aria-valuetext", text);
      }
    }
  }, [handles]);

  const stop = React.useCallback(() => {
    cancelAnimationFrame(frame.current);
    frame.current = 0;
  }, []);

  const run = React.useCallback(() => {
    if (frame.current) return;
    last.current = 0;
    const step = (now: number) => {
      const dt = last.current ? Math.min((now - last.current) / 1000, MOST_DT) : 1 / 60;
      last.current = now;
      const calm = asksForStillness();
      const s = state.current;
      const alive = playRef.current && !calm;
      if (alive) {
        s.clock += dt;
        const pose = armAt(s.clock);
        s.phi = pose.phi;
        s.pitch = pose.pitch;
        s.spin += spinAt(s.clock) * SPIN_RATE * dt;
        s.turn = follow(s.turn, spinAt(s.clock), dt, TURNING);
      } else if (calm) {
        s.phi = s.wantPhi;
        s.pitch = s.wantPitch;
        s.turn = 0;
      } else {
        s.phi = follow(s.phi, s.wantPhi, dt, SEEK);
        s.pitch = follow(s.pitch, s.wantPitch, dt, SEEK);
        s.turn = follow(s.turn, 0, dt, TURNING);
      }
      paint();
      const settled = s.phi === s.wantPhi && s.pitch === s.wantPitch && Math.abs(s.turn) < 0.004;
      frame.current = alive || (!calm && !settled) ? requestAnimationFrame(step) : 0;
    };
    frame.current = requestAnimationFrame(step);
  }, [paint]);

  React.useEffect(() => {
    if (inView) run();
    else stop();
  }, [inView, run, stop]);

  React.useEffect(() => {
    playRef.current = playing;
    const s = state.current;
    if (playing) {
      // pick the side up where the arm was left standing
      s.clock = tourTimeFor(clampPhi(s.phi));
      s.wantPhi = s.phi;
      s.wantPitch = s.pitch;
    } else {
      // put it down where it stands, and let the reader take it from there
      s.wantPhi = clampPhi(s.phi);
      s.wantPitch = 0;
    }
    if (playing && inView) run();
    else if (!playing) run();
  }, [playing, inView, run]);

  React.useEffect(() => () => stop(), [stop]);
  React.useEffect(() => paint(), [paint]);

  const pivotAngle = (clientX: number, clientY: number) => {
    const box = root.current?.getBoundingClientRect();
    if (!box || !box.width || !box.height) return null;
    const at: Flat = [((clientX - box.left) / box.width) * WIDTH, ((clientY - box.top) / box.height) * HEIGHT];
    const [x, y] = planeFrom(at, P, ARM_Z);
    const dx = x - PIVOT[0];
    const dy = y - PIVOT[1];
    // a pointer hard by the post points everywhere at once, so it is ignored
    if (Math.hypot(dx, dy) < NEAR) return null;
    return Math.atan2(dy, dx);
  };

  const seekTo = React.useCallback(
    (phi: number) => {
      const s = state.current;
      s.wantPhi = clampPhi(phi);
      s.wantPitch = 0;
      run();
    },
    [run],
  );

  return (
    <div className={className ? `iso the-turntable ${className}` : "iso the-turntable"} data-theme={theme}>
      <div className="the-turntable-plate">
        <div
          ref={root}
          className="the-turntable-stage"
          role="slider"
          tabIndex={playing ? -1 : 0}
          data-interactive={playing ? undefined : ""}
          aria-label="A turntable: the arm swings across the record as the platter turns. Stop it and drag the arm to any groove."
          aria-readonly={playing}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={0}
          aria-valuetext="parked, off the record"
          style={{ touchAction: "pan-y" }}
          onPointerDown={(event) => {
            if (playing) return;
            const psi = pivotAngle(event.clientX, event.clientY);
            if (psi === null) return;
            event.currentTarget.setPointerCapture(event.pointerId);
            // hold the arm where it stands rather than throwing it at the pointer
            grab.current = state.current.phi - psi;
            setPressing(true);
            seekTo(psi + grab.current);
          }}
          onPointerMove={(event) => {
            if (playing || !pressing) return;
            const psi = pivotAngle(event.clientX, event.clientY);
            if (psi === null) return;
            seekTo(psi + grab.current);
          }}
          onPointerUp={(event) => {
            if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
            setPressing(false);
          }}
          onPointerCancel={() => setPressing(false)}
          onKeyDown={(event) => {
            if (playing) return;
            if (event.key === "Home") {
              event.preventDefault();
              seekTo(PHI_PARK);
              return;
            }
            if (event.key === "End") {
              event.preventDefault();
              seekTo(PHI_INNER);
              return;
            }
            if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
            event.preventDefault();
            // the value is a distance from the spindle, so the keys step that:
            // stepping the bearing instead would do nothing at the rim and
            // everything at the label
            const here = Math.max(0, Math.min(1, sideAt(state.current.wantPhi)));
            const step = event.shiftKey ? 0.16 : 0.05;
            const next = here + (event.key === "ArrowRight" ? step : -step);
            if (next <= 0) seekTo(PHI_PARK);
            else seekTo(bearingFor(GROOVE_OUT + (GROOVE_IN - GROOVE_OUT) * Math.min(1, next)));
          }}
        >
          <IsoFigure
            width={WIDTH}
            height={HEIGHT}
            className="the-turntable-figure"
            label="A turntable in isometric view: the platter spins while the tonearm swings in, sets the stylus down on the record and creeps toward the label"
          >
            {DECK_PARTS.map((item, index) => (
              <Solid key={`deck${index}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} className={item.mark} />
            ))}
            {DECK_LINES.map((item, index) => (
              <Line key={`ink${index}`} d={item.d} tone={item.tone} className={item.className} />
            ))}

            {/* the labels turn with the platter, so each rides its own group: the
                groove and print at the record's face, the index mark one level
                down on the platter itself */}
            {PLATTER_PARTS.map((item, index) => (
              <Solid key={`platter${index}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} />
            ))}
            {PLATTER_LINES.map((item, index) => (
              <Line key={`platterink${index}`} d={item.d} tone={item.tone} className={item.className} />
            ))}
            <Dots points={STROBE} size={0.85} tone="lo" />
            <g ref={rim}>
              <Line d={INDEX_MARK.d} tone={INDEX_MARK.tone} />
            </g>
            <g ref={grooves}>
              <Line d={GROOVE} tone="faint" />
              {LABEL_MARKS.map((item, index) => (
                <Line key={`mark${index}`} d={item.d} tone={item.tone} className={item.className} />
              ))}
            </g>

            {FRONT_PARTS.map((item, index) => (
              <Solid key={`front${index}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} />
            ))}
            {FRONT_LINES.map((item, index) => (
              <Line key={`frontink${index}`} d={item.d} tone={item.tone} className={item.className} />
            ))}

            {OPENING.map((paths, index) => (
              <LiveSolid
                key={`arm${index}`}
                paths={paths}
                handle={handles[index]}
                tone={ARM_STYLE[index]!.tone}
                crease={ARM_STYLE[index]!.crease}
                lit={ARM_STYLE[index]!.lit}
                className={ARM_STYLE[index]!.mark}
              />
            ))}
            <path ref={lamp} className="iso-line the-turntable-led" data-tone="red" d={LAMP_RING} />
          </IsoFigure>
        </div>

        <button
          type="button"
          className="the-turntable-control"
          aria-label={playing ? "Pause the animation and take the arm" : "Play the animation"}
          title={playing ? "Pause" : "Play"}
          onClick={() => setPlaying(!playing)}
        >
          <span className="the-turntable-swap" aria-hidden="true">
            <HugeiconsIcon className="the-turntable-glyph" data-on={playing ? "" : undefined} icon={PauseIcon} size={16} strokeWidth={1.6} />
            <HugeiconsIcon className="the-turntable-glyph" data-on={playing ? undefined : ""} icon={PlayIcon} size={16} strokeWidth={1.6} />
          </span>
        </button>
      </div>
    </div>
  );
}

// The turntable. One clock, three numbers: how far the platter has turned,
// where the arm points, and how high it rides. Everything else is bolted down.
//
// The deck, the platter and the record are all stacks of discs, so the kit's
// extrude() draws them. The arm is a rigid body swinging about a vertical post
// and tipping about a horizontal one, which extrude() cannot follow; it is built
// along a frame in axis-parts.ts and rebuilt from the two numbers, whole, every
// frame. Nothing on the arm is transformed: it is placed.
import {
  circleRing,
  corners,
  cylinder,
  fitProjection,
  iso,
  knurl,
  lineOnTop,
  pathOf,
  ring,
  sideArc,
  slabOf,
  type Flat,
  type LineTone,
  type Plan,
  type Plane,
  type Point3,
  type Projection,
  type SolidPaths,
  type Tone,
} from "@/components/anatomy/iso-kit";
import {
  barBetween,
  circleSection,
  frameAlong,
  pointOn,
  prismOf,
  rectSection,
  spinTransform,
  type Frame,
} from "@/components/anatomy/axis-parts";

export const WIDTH = 640;
export const HEIGHT = 420;
const PAD = 18;

/* ——— the deck, in millimetres, origin at the centre of the top face ——— */
export const PLINTH: Plan = { x: -250, y: -200, w: 500, d: 400, r: 15 };
export const TOP: Plan = { x: -234, y: -184, w: 468, d: 368, r: 9 };
export const FOOT_H = 13;
export const BODY_H = 44;
export const TOP_H = 3;
export const BODY_Z = FOOT_H;
export const TOP_Z = FOOT_H + BODY_H;
export const DECK_Z = TOP_Z + TOP_H;
export const FOOT_R = 17;
export const FEET: Plane[] = [
  [-204, -154],
  [204, -154],
  [-204, 154],
  [204, 154],
];

/* ——— the platter, the mat and the record ——— */
export const PLATTER_C: Plane = [-46, 12];
export const PLATTER_R = 154;
export const PLATTER_H = 22;
export const PLATTER_Z0 = DECK_Z;
export const PLATTER_Z1 = PLATTER_Z0 + PLATTER_H;
export const MAT_R = 147;
export const MAT_H = 3;
export const RECORD_R = 141;
export const RECORD_H = 2;
export const RECORD_Z1 = PLATTER_Z1 + MAT_H + RECORD_H;
export const LABEL_R = 46;
export const LABEL_H = 0.8;
export const SPINDLE_R = 3.4;

/* ——— the arm: a post at the back right, reaching back over the record ——— */
export const PIVOT: Plane = [152, -96];
export const ARM_Z = 104;
export const ARM_L = 232;
const REACH = 400;
/** the stylus rides this far from the spindle when the side starts and ends */
export const GROOVE_OUT = 136;
export const GROOVE_IN = 52;
/** parked, the arm points at the front right corner of the deck */
export const PHI_PARK = (84 * Math.PI) / 180;
export const PITCH_MAX = (2.6 * Math.PI) / 180;

const SPAN = Math.hypot(PLATTER_C[0] - PIVOT[0], PLATTER_C[1] - PIVOT[1]);
export const PHI_CENTRE = Math.atan2(PLATTER_C[1] - PIVOT[1], PLATTER_C[0] - PIVOT[0]);
/** how far off the pivot-to-spindle line the arm sits to reach a groove */
export const swingFor = (radius: number) =>
  Math.acos(Math.max(-1, Math.min(1, (SPAN * SPAN + ARM_L * ARM_L - radius * radius) / (2 * SPAN * ARM_L))));
export const PHI_OUTER = PHI_CENTRE - swingFor(GROOVE_OUT);
export const PHI_INNER = PHI_CENTRE - swingFor(GROOVE_IN);
/** the bearing that puts the stylus a given distance from the spindle: the way
    back from a groove, where the arm has no say in where the value lands */
export const bearingFor = (radius: number) => PHI_CENTRE - swingFor(radius);
/** the park clip catches the arm beside the headshell */
export const REST_AT: Plane = [
  PIVOT[0] + 200 * Math.cos(PHI_PARK),
  PIVOT[1] + 200 * Math.sin(PHI_PARK),
];
export const REST_Z = 107;

const PIVOT_AT: Point3 = [PIVOT[0], PIVOT[1], ARM_Z];

/** The arm's frame: its axis points where the arm points and tips with the cue
    lever, and its cross-section plane rides the arm, so every part on it moves
    as one body when either number changes. */
export function armFrame(phi: number, pitch: number): Frame {
  return frameAlong(PIVOT_AT, [
    PIVOT_AT[0] + REACH * Math.cos(pitch) * Math.cos(phi),
    PIVOT_AT[1] + REACH * Math.cos(pitch) * Math.sin(phi),
    PIVOT_AT[2] + REACH * Math.sin(pitch),
  ]);
}

/** every point either drawn or swept through, so one camera holds both ends of
    the travel: the arm is fitted parked and at the run-out, cue raised. */
function extremes(): Point3[] {
  const out: Point3[] = [];
  const prism = (plan: Plan, z0: number, z1: number) => {
    for (const [x, y] of corners(plan, 0)) out.push([x, y, z0], [x, y, z1]);
  };
  prism(PLINTH, 0, BODY_Z + BODY_H);
  prism(TOP, TOP_Z, DECK_Z);
  for (const [x, y] of circleRing(PLATTER_C[0], PLATTER_C[1], PLATTER_R, 20)) {
    out.push([x, y, PLATTER_Z1], [x, y, RECORD_Z1]);
  }
  out.push([PLATTER_C[0], PLATTER_C[1], RECORD_Z1 + 14]);
  for (const phi of [PHI_PARK, PHI_INNER]) {
    const frame = armFrame(phi, PITCH_MAX);
    for (const s of [-88, 0, 60, 140, 200, 234]) {
      for (const v of [-17, 0]) out.push(pointOn(frame, s, [v, v]), pointOn(frame, s, [16, 0]), pointOn(frame, s, [-16, 0]));
    }
  }
  out.push([REST_AT[0], REST_AT[1], REST_Z], [PIVOT[0], PIVOT[1], ARM_Z + 16]);
  return out;
}

export const P: Projection = fitProjection(extremes(), WIDTH, HEIGHT, { pad: PAD });
/* ——— what a drawing is made of: a solid, or a line across the faces ——— */
export interface Part {
  paths: SolidPaths;
  tone: Tone;
  crease: Tone | "none";
  lit: boolean;
  /** a hook for CSS, for the one part that has a state of its own */
  mark?: string;
}

export interface Ink {
  d: string;
  tone: LineTone;
  className?: string;
}

const part = (paths: SolidPaths, tone: Tone = "mid", crease: Tone | "none" = "faint", lit = false, mark?: string): Part => ({ paths, tone, crease, lit, mark });
const ink = (d: string, tone: LineTone = "lo", className?: string): Ink => ({ d, tone, className });

/* ——— the deck: plinth on four feet, a top face, and the controls ——— */
export const DECK_PARTS: Part[] = [];
export const DECK_LINES: Ink[] = [];
/** the two fittings the platter would paint over: they stand in front of it */
export const FRONT_PARTS: Part[] = [];
export const FRONT_LINES: Ink[] = [];

for (const [x, y] of FEET) {
  DECK_PARTS.push(part(cylinder(x, y, FOOT_R + 2, 0, 6, P, 20, 1.5), "mid"));
  DECK_PARTS.push(part(cylinder(x, y, FOOT_R - 4, 6, FOOT_H - 6, P, 18, 0.6), "mid"));
}

DECK_PARTS.push(part(slabOf(PLINTH, BODY_Z, BODY_H, P, 12, 2), "mid"));
DECK_PARTS.push(part(slabOf(TOP, TOP_Z, TOP_H, P, 12, 0.5), "hi"));

/* corner screws, and the slot cut across each one */
for (const [x, y] of corners(TOP, 20)) {
  DECK_PARTS.push(part(cylinder(x, y, 4.4, DECK_Z, 1.1, P, 12, 0.4), "mid"));
  DECK_LINES.push(ink(lineOnTop([x - 3.2, y], [x + 3.2, y], DECK_Z + 1.1, P), "lo"));
}

/* the power lamp, lit while the platter turns */
DECK_PARTS.push(part(cylinder(-205, -152, 7, DECK_Z, 1.6, P, 16, 0.5), "mid"));
DECK_PARTS.push(part(cylinder(-205, -152, 3.4, DECK_Z + 1.6, 1, P, 12, 0.3), "hi", "faint", true));
/** the ring itself is drawn live, because its brightness is the motor's */
export const LAMP_RING = ring(-205, -152, 3.4, DECK_Z + 2.6, P, 14);

/* start and stop, and the speed selector */
DECK_PARTS.push(part(cylinder(-206, 120, 22, DECK_Z, 2, P, 24, 0.6), "lo"));
DECK_PARTS.push(part(cylinder(-206, 120, 18, DECK_Z + 2, 4.4, P, 24, 1.3), "hi", "faint", true));
DECK_PARTS.push(part(cylinder(-212, 58, 16, DECK_Z, 1.6, P, 20, 0.5), "lo"));
DECK_PARTS.push(part(cylinder(-212, 58, 12.5, DECK_Z + 1.6, 3, P, 20, 0.9), "hi", "faint", true));

/* the pitch fader: a raised bezel with a recess in it and a knob riding it */
FRONT_PARTS.push(part(slabOf({ x: 195, y: -34, w: 20, d: 108, r: 4 }, DECK_Z, 1.4, P, 6, 0.4), "mid"));
FRONT_PARTS.push(part(slabOf({ x: 199, y: -30, w: 12, d: 100, r: 2 }, DECK_Z + 1.4, 0.7, P, 6, 0.2), "lo"));
FRONT_PARTS.push(part(slabOf({ x: 197.5, y: 8, w: 15, d: 24, r: 2.5 }, DECK_Z + 2.1, 4.4, P, 8, 0.7), "hi", "faint", true));
FRONT_LINES.push(ink(lineOnTop([199.5, 20], [210.5, 20], DECK_Z + 6.5, P), "lo"));

/* the 45 adapter, parked on the deck */
DECK_PARTS.push(part(cylinder(-170, -160, 20, DECK_Z, 1.6, P, 24, 0.6), "mid"));
DECK_PARTS.push(part(cylinder(-170, -160, 12, DECK_Z + 1.6, 4.4, P, 20, 0.9), "hi", "faint", true));
DECK_LINES.push(ink(ring(-170, -160, 7, DECK_Z + 6, P, 18), "faint"));

/* the nameplate */
DECK_PARTS.push(part(slabOf({ x: 10, y: -170, w: 96, d: 30, r: 4 }, DECK_Z, 0.9, P, 6, 0.3), "mid"));
for (const [row, width] of [[-162, 52], [-155, 72], [-148, 40]]) {
  DECK_LINES.push(ink(lineOnTop([24, row], [24 + width, row], DECK_Z + 0.9, P), "lo"));
}

/* the arm rest: a stem with a cradle that catches the arm when it parks */
FRONT_PARTS.push(part(cylinder(REST_AT[0], REST_AT[1], 12, DECK_Z, 6, P, 18, 0.8), "mid"));
FRONT_PARTS.push(part(cylinder(REST_AT[0], REST_AT[1], 6, DECK_Z + 6, REST_Z - 3, P, 14, 0.6), "mid"));
for (const side of [-1, 1] as const) {
